{
  "name": "PureFin Report Template",
  "description": "A clean, screenshot-optimized financial reporting template focusing on Sales, Fees, COGS, Shipping, and Profit."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface FinancialData {
  sales: number;
  sellingFee: number;
  cogs: number;
  shipping: number;
}

export type CurrencyCode = 'USD' | 'EUR' | 'GBP' | 'JPY';

import React from 'react';
import { LucideIcon } from 'lucide-react';

interface MetricCardProps {
  label: string;
  amount: number;
  isNegative?: boolean;
  icon: LucideIcon;
  colorClass: string;
  bgClass: string;
  onChange?: (value: number) => void;
  isEditable?: boolean;
}

export const MetricCard: React.FC<MetricCardProps> = ({
  label,
  amount,
  isNegative = false,
  icon: Icon,
  colorClass,
  bgClass,
  onChange,
  isEditable = true
}) => {
  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD',
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    }).format(val);
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (onChange) {
      const val = parseFloat(e.target.value);
      onChange(isNaN(val) ? 0 : val);
    }
  };

  return (
    <div className={`relative overflow-hidden rounded-2xl border border-white/5 p-6 backdrop-blur-xl transition-all duration-300 ${bgClass}`}>
      <div className="flex items-start justify-between mb-4">
        <div className={`p-3 rounded-xl bg-white/10 ${colorClass}`}>
          <Icon size={24} />
        </div>
        {isEditable && (
           <div className="opacity-0 group-hover:opacity-100 transition-opacity absolute top-4 right-4">
             {/* Edit indicator could go here */}
           </div>
        )}
      </div>

      <div className="space-y-1">
        <p className="text-sm font-medium text-gray-400 uppercase tracking-wider">{label}</p>

        <div className="flex items-baseline gap-2">
          {isEditable ? (
             <div className="relative group">
                <input
                  type="number"
                  value={amount}
                  onChange={handleInputChange}
                  className="bg-transparent text-3xl font-bold text-white focus:outline-none focus:ring-0 w-full [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none border-b border-transparent focus:border-white/20 transition-colors"
                />
                <span className="absolute left-0 -top-6 text-xs text-gray-500 opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none">
                  Click to edit
                </span>
             </div>
          ) : (
            <h3 className={`text-3xl font-bold ${isNegative ? 'text-red-400' : 'text-white'}`}>
              {formatCurrency(amount)}
            </h3>
          )}
        </div>
      </div>

      {/* Decorative gradient blob */}
      <div className={`absolute -right-6 -bottom-6 w-24 h-24 rounded-full blur-2xl opacity-20 ${colorClass.replace('text-', 'bg-')}`}></div>
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { 
  DollarSign, 
  ShoppingBag, 
  Package, 
  Truck, 
  TrendingUp,
  Camera,
  Edit3
} from 'lucide-react';
import { MetricCard } from './components/MetricCard';
import { FinancialData } from './types';

const App: React.FC = () => {
  const [isEditMode, setIsEditMode] = useState(true);
  const [data, setData] = useState<FinancialData>({
    sales: 12500.00,
    sellingFee: 1875.50,
    cogs: 4200.00,
    shipping: 850.25,
  });

  const profit = data.sales - (data.sellingFee + data.cogs + data.shipping);
  const profitMargin = data.sales > 0 ? (profit / data.sales) * 100 : 0;

  const updateField = (field: keyof FinancialData) => (value: number) => {
    setData(prev => ({ ...prev, [field]: value }));
  };

  const reportRef = useRef<HTMLDivElement>(null);

  return (
    <div className="min-h-screen bg-[#050505] text-white flex flex-col items-center justify-center p-4 md:p-8 relative selection:bg-indigo-500/30">

      {/* Background Ambience */}
      <div className="fixed inset-0 z-0 pointer-events-none">
        <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-indigo-900/20 rounded-full blur-[128px]" />
        <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-emerald-900/10 rounded-full blur-[128px]" />
      </div>

      {/* Control Bar (Hidden in Screenshot if desired, but user can just crop) */}
      <div className="fixed top-6 z-50 flex gap-4 bg-white/5 backdrop-blur-md p-2 rounded-full border border-white/10 shadow-2xl">
        <button
          onClick={() => setIsEditMode(!isEditMode)}
          className={`flex items-center gap-2 px-4 py-2 rounded-full text-sm font-medium transition-all ${
            isEditMode 
              ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/25' 
              : 'text-gray-400 hover:text-white hover:bg-white/5'
          }`}
        >
          <Edit3 size={16} />
          {isEditMode ? 'Editing On' : 'View Mode'}
        </button>
        <div className="w-px bg-white/10 h-full mx-1"></div>
        <div className="px-4 py-2 text-xs text-gray-500 font-mono flex items-center">
          <Camera size={14} className="mr-2" />
          Optimized for Screenshots
        </div>
      </div>

      {/* Main Report Container */}
      <div 
        ref={reportRef}
        className="relative z-10 w-full max-w-5xl mx-auto"
      >
        <div className="bg-[#0a0a0a] border border-white/5 shadow-2xl rounded-3xl p-8 md:p-12 lg:p-16 overflow-hidden relative">
           {/* Subtle Grid Pattern overlay */}
          <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-20 pointer-events-none"></div>

          {/* Header */}
          <div className="mb-12 flex justify-between items-end relative z-10">
            <div>
              <h1 className="text-4xl md:text-5xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-white via-white to-gray-500 tracking-tight mb-2">
                Financial Report
              </h1>
              <p className="text-gray-500 font-medium">Performance Overview</p>
            </div>
            <div className="text-right hidden sm:block">
              <div className="text-sm text-gray-500 uppercase tracking-widest mb-1">Total Profit</div>
              <div className={`text-2xl font-bold ${profit >= 0 ? 'text-emerald-400' : 'text-red-400'}`}>
                {new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(profit)}
              </div>
            </div>
          </div>

          {/* Grid Layout */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8 relative z-10">

            {/* Sales */}
            <MetricCard 
              label="Sales" 
              amount={data.sales} 
              icon={DollarSign}
              colorClass="text-blue-400"
              bgClass="bg-blue-500/5 hover:bg-blue-500/10"
              onChange={updateField('sales')}
              isEditable={isEditMode}
            />

            {/* Selling Fee */}
            <MetricCard 
              label="Selling Fee" 
              amount={data.sellingFee} 
              icon={ShoppingBag}
              colorClass="text-orange-400"
              bgClass="bg-orange-500/5 hover:bg-orange-500/10"
              isNegative
              onChange={updateField('sellingFee')}
              isEditable={isEditMode}
            />

            {/* COGS */}
            <MetricCard 
              label="Cost of Goods" 
              amount={data.cogs} 
              icon={Package}
              colorClass="text-purple-400"
              bgClass="bg-purple-500/5 hover:bg-purple-500/10"
              isNegative
              onChange={updateField('cogs')}
              isEditable={isEditMode}
            />

            {/* Shipping */}
            <MetricCard 
              label="Shipping" 
              amount={data.shipping} 
              icon={Truck}
              colorClass="text-yellow-400"
              bgClass="bg-yellow-500/5 hover:bg-yellow-500/10"
              isNegative
              onChange={updateField('shipping')}
              isEditable={isEditMode}
            />
          </div>

          {/* Profit Section - The Big Finish */}
          <div className="relative z-10">
            <div className={`rounded-2xl p-8 flex flex-col md:flex-row items-center justify-between transition-colors duration-500 ${
              profit >= 0 
                ? 'bg-gradient-to-r from-emerald-950/50 to-emerald-900/20 border border-emerald-500/20' 
                : 'bg-gradient-to-r from-red-950/50 to-red-900/20 border border-red-500/20'
            }`}>
              <div className="flex items-center gap-6 mb-6 md:mb-0">
                <div className={`p-4 rounded-full ${profit >= 0 ? 'bg-emerald-500/20 text-emerald-400' : 'bg-red-500/20 text-red-400'}`}>
                  <TrendingUp size={32} />
                </div>
                <div>
                  <h2 className="text-lg font-medium text-gray-300 uppercase tracking-wide">Net Profit</h2>
                  <p className="text-sm text-gray-500">
                    {profitMargin.toFixed(1)}% Margin
                  </p>
                </div>
              </div>

              <div className="text-center md:text-right">
                <div className={`text-5xl md:text-6xl font-bold tracking-tight ${
                  profit >= 0 ? 'text-white' : 'text-red-400'
                }`}>
                  {new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(profit)}
                </div>
              </div>
            </div>
          </div>

          {/* Footer for Screenshot Validity */}
          <div className="mt-8 pt-6 border-t border-white/5 flex justify-between items-center text-xs text-gray-600 font-mono">
            <span>GENERATED REPORT</span>
            <span>PUREFIN TEMPLATE</span>
          </div>

        </div>
      </div>
    </div>
  );
};

export default App;

