import React, { useState, useRef, useEffect } from 'react';
import { LucideIcon } from 'lucide-react';

interface MetricCardProps {
  label: string;
  amount: number;
  isNegative?: boolean;
  icon: LucideIcon;
  iconColor: string;
  accentColor: string;
  onChange?: (value: number) => void;
}

export const MetricCard: React.FC<MetricCardProps> = ({
  label,
  amount,
  isNegative = false,
  icon: Icon,
  iconColor,
  accentColor,
  onChange
}) => {
  const [isEditing, setIsEditing] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (isEditing && inputRef.current) {
      inputRef.current.focus();
    }
  }, [isEditing]);

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD',
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    }).format(val);
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (onChange) {
      const val = parseFloat(e.target.value);
      onChange(isNaN(val) ? 0 : val);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      setIsEditing(false);
    }
  };

  return (
    <div 
      onClick={() => setIsEditing(true)}
      className="group relative bg-zinc-950 p-6 rounded-xl border border-zinc-900 shadow-sm transition-all hover:border-zinc-800 w-full cursor-pointer hover:bg-zinc-900/20"
    >

      {/* Subtle indicator bar on left for active visual hierarchy */}
      <div className={`absolute left-0 top-4 bottom-4 w-0.5 rounded-r-full transition-opacity opacity-50 group-hover:opacity-100 ${accentColor}`}></div>

      <div className="flex items-center justify-between mb-3">
        <div className="flex items-center gap-2.5">
          <div className={`${iconColor} opacity-80`}>
            <Icon size={16} strokeWidth={2} />
          </div>
          <p className="text-[11px] font-bold text-zinc-500 uppercase tracking-widest truncate select-none">{label}</p>
        </div>
      </div>

      <div className="flex items-baseline relative z-10 min-h-[40px]">
        {isEditing ? (
            <div className="w-full relative">
              <span className="absolute left-0 top-1/2 -translate-y-1/2 text-lg text-zinc-600 font-light select-none">$</span>
              <input
                ref={inputRef}
                type="number"
                value={amount}
                onChange={handleInputChange}
                onBlur={() => setIsEditing(false)}
                onKeyDown={handleKeyDown}
                className="bg-transparent text-2xl md:text-3xl font-light text-zinc-100 focus:outline-none w-full pl-4 py-1 placeholder-zinc-800 [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none transition-colors border-b border-zinc-800"
              />
            </div>
        ) : (
          <h3 className={`text-2xl md:text-3xl font-light tracking-tight tabular-nums select-none ${isNegative ? 'text-zinc-100' : 'text-zinc-100'}`}>
            {formatCurrency(amount)}
          </h3>
        )}
      </div>
    </div>
  );
};

