            className={`text-2xl lg:text-3xl font-light tracking-tight tabular-nums select-none truncate w-full text-right drop-shadow-sm ${textColor ? textColor : 'text-zinc-100'}`}
            title={formatCurrency(amount)}
          >
            {formatCurrency(amount)}
          </h3>

          {subItems && subItems.length > 0 && (
            <div className="flex flex-col items-end gap-1 mt-2 w-full">
              {subItems.map((item, idx) => (
                <div key={idx} className="flex items-center justify-end gap-2 text-[10px] text-zinc-400 font-medium tracking-wide">
                  <div className="flex items-center gap-1.5 opacity-80">
                    {item.icon && <item.icon size={12} />}
                    <span>{item.label}</span>
                  </div>
                  <span className="tabular-nums text-zinc-300">
                    {formatCurrency(item.amount)}
                  </span>
                </div>
              ))}
            </div>
          )}
      </div>
    </div>
  );
};

